int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size; i++) {
            if (buf[i] == 0x1F) {
                dctx->frame_start_found = 1;
                dctx->current_position = i;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int header_length = 10; // typical header length
        if (dctx->current_position + header_length <= buf_size) {
            // Extract frame dimensions from the header
            int width = ((buf[dctx->current_position + 1] & 0x0F) << 8) | buf[dctx->current_position + 2];
            int height = ((buf[dctx->current_position + 3] & 0x0F) << 8) | buf[dctx->current_position + 4];

            // Compute frame size
            int frame_size = width * height * 2;

            // Compute remaining bytes
            int remaining_bytes = frame_size - (dctx->current_position + header_length);
            if (remaining_bytes <= 0) {
                dctx->frame_start_found = 0;
                return remaining_bytes;
            }
        } else {
            // Not enough data to determine the end of the frame
            dctx->current_position += buf_size;
            return END_NOT_FOUND;
        }
    }

    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
