        for (int i = 0; i < buf_size; i++) {
            if (buf[i] == 0x1f && buf[i + 1] == 0x40) {
                dctx->frame_start = i;
                dctx->frame_start_found = 1;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int header_bytes = buf_size - dctx->frame_start;
        int frame_size = get_frame_size_from_header(&buf[dctx->frame_start], header_bytes);
        if (frame_size <= 0) {
            return END_NOT_FOUND;
        }

        int bytes_remaining = frame_size - dctx->frame_bytes_read;
        if (bytes_remaining <= 0) {
            dctx->frame_start_found = 0;
            dctx->frame_bytes_read = 0;
            return frame_size;
        }

        if (buf_size >= bytes_remaining) {
            dctx->frame_start_found = 0;
            dctx->frame_bytes_read = 0;
            return frame_size;
        } else {
            dctx->frame_bytes_read += buf_size;
            return END_NOT_FOUND;
        }
    }

    return END_NOT_FOUND;
}

